  // Probabilité forte : 200–300
  min = 200;
  max = 300;
} else if (r < 0.85) {
  // Probabilité moyenne : 80–199
  min = 80;
  max = 199;
} else {
  // Probabilité plus faible : 301–540
  min = 301;
  max = 540;
}

return Math.floor(Math.random() * (max - min + 1)) + min;

